#define NUM_KAT_VECTORS (sizeof(kat_vectors) / sizeof(kat_vectors[0]))

static void
print_bytes_hex(const uint8_t *bytes, size_t len)
{
	for (size_t i = 0; i < len; ++i) {
		print(h,bytes[i],2);
	}
}

static int
compare_bytes(const uint8_t *a, const uint8_t *b, size_t len)
{
	for (size_t i = 0; i < len; ++i) {
		if (a[i] != b[i]) return 0;
	}
	return 1;
}

int
main(void)
{
	uint8_t out[CRYPTO_BYTES];
	size_t passed = 0, failed = 0;

	print("ASCON Hash KAT Test\n");
	print("===================\n\n");
	print("Running ")(u,NUM_KAT_VECTORS)(" test vectors...\n\n");

	for (size_t i = 0; i < NUM_KAT_VECTORS; ++i) {
		const KatVector *kv = &kat_vectors[i];

		/* compute hash */
		crypto_hash(out, kv->msg, kv->msg_len);

		/* compare with expected */
		if (compare_bytes(out, kv->md, CRYPTO_BYTES)) {
			++passed;
			print("Test ")(u,i+1)(": PASS (msg_len=")(u,kv->msg_len)(")\n");
		} else {
			++failed;
			print("Test ")(u,i+1)(": FAIL (msg_len=")(u,kv->msg_len)(")\n");
			print("  Expected: ");
			print_bytes_hex(kv->md, CRYPTO_BYTES);
			print("\n  Got:      ");
			print_bytes_hex(out, CRYPTO_BYTES);
			print("\n");
		}
	}

	print("\n===================\n");
	print("Results: ")(u,passed)(" passed, ")(u,failed)(" failed\n");

	if (failed == 0) {
		print("\n\033[0;32mALL TESTS PASSED!\033[0m\n");
		return 0;
	} else {
		print("\n\033[0;31mSOME TESTS FAILED!\033[0m\n");
		return 1;
	}
}

